        if not getattr(me,"bot",False) or str(getattr(me,"username","")).casefold()!=USERNAME.casefold():
            raise MTSetupError("connected_account_is_not_expected_bot")
        from telethon import events
        code=secrets.token_hex(5).upper()
        paired=asyncio.get_running_loop().create_future()
        @client.on(events.NewMessage(incoming=True))
        async def pair_message(event):
            if paired.done():return
            if not event.is_private or event.out:return
            if (event.raw_text or "").strip()!="/start "+code:return
            sender=int(event.sender_id or 0)
            if sender<=0 or int(event.chat_id or 0)!=sender:return
            if getattr(event.sender,"bot",False):return
            paired.set_result((sender,int(event.message.id)))
        print("In Telegram open @"+USERNAME+" and send exactly:")
        print("/start "+code)
        print("Waiting for this new private message through TGWS...")
