        from telethon.sessions import StringSession
        saved=StringSession.save(client.session)
        if not saved:raise MTSetupError("authorized_session_not_serializable")
        # Store encrypted values only after bot identity and private sender verified.
        BASE.mkdir(parents=True,exist_ok=True)
        if CREDS.exists() or SESSION.exists():
            raise MTSetupError("existing_mtproto_auth_store_refuse_overwrite")
        store_session(saved)
        dpapi_write({
